import{bQ as t,aL as e,u as i,G as s}from"./chunks/framework.DaEK0KQB.js";const g=JSON.parse('{"title":"github工作流","description":"","frontmatter":{"title":"github工作流","date":"2023-04-21T11:24:27.000Z","permalink":"/pages/d0c868/","categories":["github","实操"],"tags":[null]},"headers":[],"relativePath":"github/实操/01.github工作流.md","filePath":"github/实操/01.github工作流.md","lastUpdated":1785224938000}'),n={name:"github/实操/01.github工作流.md"};function l(r,a,p,u,c,o){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="好用的-github-工作流" tabindex="-1">好用的 github 工作流 <a class="header-anchor" href="#好用的-github-工作流" aria-label="Permalink to &quot;好用的 github 工作流&quot;">​</a></h1><ol><li>拉取远端仓库</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone repo_address</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>在 local git 处 新建一个 分支 feature branch</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git  checkout -b my-feature</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个时候 local git 上就存在两个分支，main branch 和 my-feature branch</p><p>修改 硬盘 代码， 修改完以后使用 git diff 看看硬盘上文件和 git 上保存的 branch 有什么区别 使用 git add file-name 将改动存在暂存区里，然后使用 git commit 将代码提交到 local git 上 使用 git push origin my-feature, 此时 github 项目上多了一个 my-feature 分支</p><ol start="3"><li>同步</li></ol><p>如果此时发现 main 直线里 多了一个 commit 名为 update</p><p>想要把 update 的 commit 也同步到 branch 里面</p><p>执行 git checkout main， 将 disk 的代码还原为 init 的状态 执行 git pull origin master , 把远端的 update 同步到 local git 的 main 分支下 执行 git checkout my-feature，切换回 my-feature 分支 git rebase main,</p><p>rebase 的意思是先把 my-feature 对 init 的改动先扔到一边，然后 main 最新修改拿过来，最后把 my-feature 修改尝试弄回去，有可能会出现 commit conflict，出现冲突要手动选择</p><p>git push -f origin my-feature， 把最新改动 push 到 github 上</p><ol start="4"><li>Pull Request</li></ol><p>将 my-feature 的改动尝试合并在 main 分支里</p><p>pull request 主分支如果接受合并，则执行 squash and merge,意思就是把其他分支的各种 commit 合并为一个改变，并把这个 commit 放到 main branch 合并后一般把远端的 feature-branch 给删掉 local git 上 还存在 feature-branch git checkout main, 首先切换到 local git 的 main 分支下 git branch -D my-feature, 把 my-feature branch 从 local git 上也删掉 git pull origin master, 把最新的更新拉到 local 的 git 和 disk 上</p>',16)])])}const d=t(n,[["render",l]]);export{g as __pageData,d as default};
